'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import { type SupportAttachment, type SupportTicket, vendorSupportService } from '@/lib/vendor/support'
import { CatalogFeedback } from '../../components/CatalogFeedback'
import { SupportAttachments } from '../../components/SupportAttachments'
import { SupportStatusBadge } from '../../components/SupportStatusBadge'

export default function SupportTicketPage({ params }: { params: Promise<{ id: string }> }) { const [vendorId, setVendorId] = useState<string | null>(null); const [ticket, setTicket] = useState<SupportTicket | null>(null); const [body, setBody] = useState(''); const [attachments, setAttachments] = useState<SupportAttachment[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); useEffect(() => { void Promise.all([params, createClient().auth.getUser()]).then(async ([route, { data: { user } }]) => { if (!user || (getUserRole(user) !== 'vendor' && getUserRole(user) !== 'admin')) return; setVendorId(user.id); setTicket(await vendorSupportService.get(user.id, route.id)); setLoading(false) }) }, [params]); async function addMessage(event: React.FormEvent) { event.preventDefault(); if (!vendorId || !ticket || !body.trim()) { setError('Message cannot be empty.'); return } try { setTicket(await vendorSupportService.addMessage(vendorId, ticket.id, body.trim(), attachments)); setBody(''); setAttachments([]); setError('') } catch { setError('We could not add your message.') } } if (loading) return <main className="vendor-page"><div className="operations-shell"><CatalogFeedback type="loading">Loading support ticket...</CatalogFeedback></div></main>; if (!ticket) return <main className="vendor-page"><div className="operations-shell"><CatalogFeedback type="error">This support ticket could not be found.</CatalogFeedback><Link href="/vendor/support" className="btn-skip">Back to support</Link></div></main>; return <main className="vendor-page"><header className="vendor-header"><Link href="/vendor/support" className="logo logo-active">Furnish<span>AI</span></Link><nav><Link href="/vendor/support" className="btn-skip">All tickets</Link><span className="vendor-header-label">Ticket details</span></nav></header><div className="operations-shell"><div className="ticket-heading"><div><p className="vendor-eyebrow">Support / {ticket.category}</p><h1>{ticket.subject}</h1><p>Created {new Date(ticket.createdAt).toLocaleString('en-IN')} · {ticket.priority} priority</p></div><SupportStatusBadge status={ticket.status} /></div><section className="ticket-thread">{ticket.messages.map((message) => <article className={`ticket-message ticket-message-${message.authorType}`} key={message.id}><div className="ticket-message-meta"><strong>{message.authorName}</strong><time>{new Date(message.createdAt).toLocaleString('en-IN')}</time></div><p>{message.body}</p>{message.attachments.length ? <div className="ticket-attachments">{message.attachments.map((attachment) => <span key={attachment.id}>{attachment.fileName}</span>)}</div> : null}</article>)}</section>{error ? <CatalogFeedback type="error">{error}</CatalogFeedback> : null}<form className="ticket-reply-form" onSubmit={(event) => void addMessage(event)}><label className="vendor-field"><span>Add a message</span><textarea rows={5} value={body} onChange={(event) => setBody(event.target.value)} placeholder="Reply to the marketplace support team" /></label><SupportAttachments attachments={attachments} onChange={setAttachments} /><button type="submit" className="btn-next">Send message</button></form></div></main> }